import React, { useState } from "react";
import { Info } from "@airbus/icons/react";
import IconButton from "../IconButton";
import Stack from "../Stack";
import Input from "../Input";
import Textarea from "../Textarea";
import FormControl from "./FormControl";
import type { Meta, StoryObj } from "@storybook/react";

const meta: Meta<typeof FormControl> = {
  id: "Components/FormControl",
  title: "General/Forms/Form Control",
  component: FormControl,
};

export default meta;
type Story = StoryObj<typeof FormControl>;

// Based on https://github.com/storybookjs/storybook/issues/12308#issuecomment-1340363567

const icons = {
  info: (
    <IconButton aria-label="Infos on form field" size="xsmall" variant="ghost">
      <Info />
    </IconButton>
  ),
  none: undefined,
};

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    label: "Label",
    helpText: "Help text",
    helpLinkLabel: "Help link",
    placeholder: "Placeholder",
  },
  argTypes: {
    labelAdornment: {
      options: Object.keys(icons),
      mapping: icons,
      control: {
        type: "select",
        labels: {
          Info: "Info",
          None: "None",
        },
      },
    },
  },
  render: (args) => (
    <FormControl {...args}>
      <Input />
    </FormControl>
  ),
};

export const Status: Story = {
  render: () => (
    <Stack spacing="2-x">
      <FormControl label="Email" error errorText="Invalid email" required>
        <Input value="@john" />
      </FormControl>
      <FormControl label="Username" success successText="Available" required>
        <Input value="john" />
      </FormControl>
    </Stack>
  ),
};

export const Adornment: Story = {
  render: () => (
    <FormControl
      required
      label="Label"
      labelAdornment={
        <IconButton
          size="xsmall"
          variant="ghost"
          aria-label="Infos on form field"
        >
          <Info />
        </IconButton>
      }
    >
      <Input />
    </FormControl>
  ),
};

export const TextArea: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [characterCount, setCharacterCount] = useState(0);
    return (
      <FormControl
        required
        label="Label"
        helpText={`${characterCount}/50`}
        placeholder="Placeholder"
      >
        <Textarea
          maxLength={50}
          onChange={(event) => setCharacterCount(event.target.value.length)}
        />
      </FormControl>
    );
  },
};
